contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        // The deployed c is owned by this test contract, so owned() should be callable.
        address beforeOwner = c.owner();
        require(beforeOwner == address(this));

        bool reverted;
        try c.owned() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted && c.owner() == address(this));
    }

    receive() external payable {}
}

